--
-- Table structure for table `Vendeur`
--

DROP TABLE IF EXISTS `Vendeur`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Vendeur` (
  `id_user` int NOT NULL,
  `nom_etablissement` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `localisation_marche` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_marche` int DEFAULT NULL,
  `latitude` double DEFAULT NULL,
  `longitude` double DEFAULT NULL,
  `score_reputation` double NOT NULL DEFAULT '0',
  PRIMARY KEY (`id_user`),
  KEY `Vendeur_id_marche_fkey` (`id_marche`),
  CONSTRAINT `Vendeur_id_marche_fkey` FOREIGN KEY (`id_marche`) REFERENCES `Marche` (`id_marche`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Vendeur_id_user_fkey` FOREIGN KEY (`id_user`) REFERENCES `Utilisateur` (`id_user`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

